def calculate_costs(data):  # Рассчитываем расходы за год из проверенных целых сумм в долларах | def объявляет функцию/метод; data — проверенный словарь сумм и месяцев; возвращает статьи, итог, финансирование и разницу бюджета.
    months = data["months"]  # Получаем число месяцев проживания за границей.
    items = [  # Собираем четыре статьи расходов для суммы и наглядной разбивки.
        {"label": "Обучение", "amount": data["tuition"]},  # Стоимость обучения уже задана за год и не умножается на месяцы.
        {"label": "Жильё", "amount": data["housing"] * months},  # Умножаем месячную аренду на срок проживания.
        {"label": "Питание и другие расходы", "amount": data["living"] * months},  # Учитываем повседневные расходы за тот же период.
        {"label": "Перелёты", "amount": data["travel"]},  # Добавляем полную сумму перелётов за год один раз.
    ]  # Завершаем список статей расходов.
    total = sum(item["amount"] for item in items)  # Складываем расходы до учёта стипендии | sum — складывает числа из перебираемой последовательности.
    funding = min(data["scholarship"], total)  # Учитываем стипендию только в пределах расходов, не моделируя дополнительные выплаты | min — выбирает меньшее значение.
    needed = total - funding  # Получаем сумму, которую студенту нужно покрыть самостоятельно.
    balance = data["budget"] - needed  # Положительное значение означает запас, отрицательное — нехватку бюджета.
    return {"items": items, "total": total, "funding": funding, "needed": needed, "balance": balance, "shortfall": max(0, -balance), "budget": data["budget"], "months": months}  # Передаём интерфейсу подробный расчёт и неотрицательную недостающую сумму | max — выбирает большее значение | return завершает вызов и отдаёт результат вызывающему коду.
